"""Download buttons for exports. Files are generated by the backend only on click."""

from __future__ import annotations

import re
import unicodedata
from collections.abc import Callable
from typing import Any

import streamlit as st

FORMATS = {
    "csv": ("CSV", "text/csv"),
    "xlsx": ("Excel", "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"),
    "pdf": ("PDF", "application/pdf"),
    "sql": ("SQL", "application/sql"),
}


def download_name(title: str, fmt: str) -> str:
    """ASCII file name derived from a title (same rule as the backend)."""
    ascii_name = unicodedata.normalize("NFKD", title).encode("ascii", "ignore").decode()
    slug = re.sub(r"[^a-z0-9]+", "-", ascii_name.lower()).strip("-")[:80].strip("-")
    return f"{slug or 'insightsql-export'}.{fmt}"


def export_fetcher(api: Any, fmt: str, **target: Any) -> Callable[[], bytes]:
    """A zero-argument callable that downloads one export.

    ``target`` is either ``analysis_id=`` or ``dataset_id=, previous=, current=, dedupe=``.
    """
    if "analysis_id" in target:
        return lambda: api.export_analysis(target["analysis_id"], fmt)
    return lambda: api.export_client_analytics(
        target["dataset_id"], target["previous"], target["current"], target["dedupe"], fmt
    )


def download_buttons(
    api: Any, title: str, key: str, formats: list[str] | None = None, **target: Any
) -> None:
    """One row of download buttons; a failed export shows the browser's download error."""
    formats = formats or list(FORMATS)
    columns = st.columns(len(formats) + 2)
    for column, fmt in zip(columns, formats, strict=False):
        label, mime = FORMATS[fmt]
        column.download_button(
            label,
            data=export_fetcher(api, fmt, **target),
            file_name=download_name(title, fmt),
            mime=mime,
            key=f"{key}_{fmt}",
            icon=":material/download:",
            on_click="ignore",
            help=f"Download as {label}",
        )
